    vector<long long> L(N);
    for (auto &x : L) cin >> x;

    int left = 0, right = N - 1;
    int operations = 0;

    while (left < right) {
        if (L[left] == L[right]) {
            ++left;
            --right;
        } else if (L[left] < L[right]) {
            L[left + 1] += L[left];
            ++left;
            ++operations;
